  ('adult-resistance-v1.0.0', 'BAND_ROW', '1.0.0', 'Soutu vastuskuminauhalla', '{"id":"exercise-band-row-v1","code":"BAND_ROW","version":"1.0.0","nameFi":"Soutu vastuskuminauhalla","method":"RESISTANCE","movementPatterns":["HORIZONTAL_PULL"],"primaryMuscles":["upper back","latissimus"],"secondaryMuscles":["biceps"],"equipment":["Vastuskuminauhat"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":1,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BAND"],"fatigue":{"systemic":1,"local":2,"neural":1,"eccentric":1,"sorenessRisk":1},"contraindicationTags":["ACUTE_SHOULDER_PAIN"],"prerequisiteTags":["SAFE_BAND_ANCHOR"],"regressionCodes":[],"progressionCodes":["ONE_ARM_ROW","SEATED_CABLE_ROW"],"substitutionCodes":["ONE_ARM_ROW","SEATED_CABLE_ROW"],"adaptationTargets":["UPPER_BODY_STRENGTH","HORIZONTAL_PULL","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Kiinnitä nauha ehjään ja vakaaseen pisteeseen.","Vedä kyynärpäät kohti kylkiä.","Palauta kädet hallitusti ja pidä hartiat rentoina."],"status":"PUBLISHED"}'::jsonb),
