  ('adult-resistance-v1.0.0', 'DEAD_BUG', '1.0.0', 'Dead bug', '{"id":"exercise-dead-bug-v1","code":"DEAD_BUG","version":"1.0.0","nameFi":"Dead bug","method":"RESISTANCE","movementPatterns":["ANTI_EXTENSION"],"primaryMuscles":["trunk"],"secondaryMuscles":["hip flexors"],"equipment":["Kehonpaino"],"environments":["HOME","GYM"],"unilateral":true,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BODYWEIGHT"],"fatigue":{"systemic":1,"local":2,"neural":1,"eccentric":1,"sorenessRisk":1},"contraindicationTags":["ACUTE_BACK_PAIN"],"prerequisiteTags":[],"regressionCodes":[],"progressionCodes":["FRONT_PLANK"],"substitutionCodes":["BIRD_DOG","FRONT_PLANK"],"adaptationTargets":["TRUNK_CONTROL","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Asetu selinmakuulle ja hengitä rauhallisesti.","Ojenna vastakkainen käsi ja jalka ilman selän asennon muuttumista.","Palaa alkuun hallitusti."],"status":"PUBLISHED"}'::jsonb),
  ('adult-resistance-v1.0.0', 'BIRD_DOG', '1.0.0', 'Bird dog', '{"id":"exercise-bird-dog-v1","code":"BIRD_DOG","version":"1.0.0","nameFi":"Bird dog","method":"RESISTANCE","movementPatterns":["ANTI_ROTATION"],"primaryMuscles":["trunk","gluteals"],"secondaryMuscles":["shoulders"],"equipment":["Kehonpaino"],"environments":["HOME","GYM"],"unilateral":true,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BODYWEIGHT"],"fatigue":{"systemic":1,"local":2,"neural":1,"eccentric":1,"sorenessRisk":1},"contraindicationTags":["ACUTE_WRIST_PAIN","ACUTE_BACK_PAIN"],"prerequisiteTags":[],"regressionCodes":[],"progressionCodes":["FRONT_PLANK"],"substitutionCodes":["DEAD_BUG","FRONT_PLANK"],"adaptationTargets":["TRUNK_CONTROL","ANTI_ROTATION","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Asetu konttausasentoon.","Ojenna vastakkainen käsi ja jalka ilman lantion kiertoa.","Palaa alkuun hitaasti ja vaihda puolta."],"status":"PUBLISHED"}'::jsonb),
  ('adult-resistance-v1.0.0', 'FRONT_PLANK', '1.0.0', 'Etulankku', '{"id":"exercise-front-plank-v1","code":"FRONT_PLANK","version":"1.0.0","nameFi":"Etulankku","method":"RESISTANCE","movementPatterns":["ANTI_EXTENSION"],"primaryMuscles":["trunk"],"secondaryMuscles":["shoulders","gluteals"],"equipment":["Kehonpaino"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BODYWEIGHT"],"fatigue":{"systemic":1,"local":3,"neural":1,"eccentric":1,"sorenessRisk":1},"contraindicationTags":["ACUTE_SHOULDER_PAIN","ACUTE_BACK_PAIN"],"prerequisiteTags":["PLANK_CONTROL"],"regressionCodes":["DEAD_BUG","BIRD_DOG"],"progressionCodes":["PALLOF_PRESS"],"substitutionCodes":["DEAD_BUG","PALLOF_PRESS"],"adaptationTargets":["TRUNK_CONTROL","ANTI_EXTENSION","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Asetu kyynärvarsien ja varpaiden varaan.","Pidä vartalo suorana ja hengitä rauhallisesti.","Lopeta ennen asennon pettämistä."],"status":"PUBLISHED"}'::jsonb),
  ('adult-resistance-v1.0.0', 'PALLOF_PRESS', '1.0.0', 'Pallof-punnerrus', '{"id":"exercise-pallof-press-v1","code":"PALLOF_PRESS","version":"1.0.0","nameFi":"Pallof-punnerrus","method":"RESISTANCE","movementPatterns":["ANTI_ROTATION"],"primaryMuscles":["trunk"],"secondaryMuscles":["shoulders","gluteals"],"equipment":["Vastuskuminauhat","Kuntosalilaitteet"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BAND","MACHINE_KG"],"fatigue":{"systemic":1,"local":2,"neural":1,"eccentric":1,"sorenessRisk":1},"contraindicationTags":["ACUTE_SHOULDER_PAIN","ACUTE_BACK_PAIN"],"prerequisiteTags":["SAFE_BAND_ANCHOR"],"regressionCodes":["DEAD_BUG"],"progressionCodes":[],"substitutionCodes":["DEAD_BUG","BAND_ROW"],"adaptationTargets":["TRUNK_CONTROL","ANTI_ROTATION","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Asetu sivuttain vastukseen nähden.","Työnnä kädet eteen vartalon kiertymättä.","Palauta kädet hallitusti rintakehän eteen."],"status":"PUBLISHED"}'::jsonb)
