values
  ('CHAIR_SQUAT', 'Tuolilta ylösnousu', 'SQUAT', array['Kehonpaino']::text[], 'Asetu tukevan tuolin eteen. Nouse hallitusti seisomaan ja laskeudu rauhallisesti takaisin. Pidä polvet varpaiden suuntaisina ja käytä kivutonta liikerataa.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-chair-squat-v1","code":"CHAIR_SQUAT","version":"1.0.0","nameFi":"Tuolilta ylösnousu","method":"RESISTANCE","movementPatterns":["SQUAT"],"primaryMuscles":["quadriceps","gluteals"],"secondaryMuscles":["trunk"],"equipment":["Kehonpaino"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":1,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BODYWEIGHT"],"fatigue":{"systemic":1,"local":2,"neural":1,"eccentric":1,"sorenessRisk":1},"contraindicationTags":["ACUTE_KNEE_PAIN","GAIT_ALTERING_PAIN"],"prerequisiteTags":[],"regressionCodes":[],"progressionCodes":["BODYWEIGHT_SQUAT","GOBLET_SQUAT"],"substitutionCodes":["BODYWEIGHT_SQUAT","LEG_PRESS"],"adaptationTargets":["GENERAL_STRENGTH","LOWER_BODY_STRENGTH","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001","CLAIM-ADULT-RT-ROM-001"],"instructionsFi":["Asetu tukevan tuolin eteen.","Nouse hallitusti seisomaan ja laskeudu rauhallisesti takaisin.","Pidä polvet varpaiden suuntaisina ja käytä kivutonta liikerataa."],"status":"PUBLISHED"}'::jsonb),
  ('BODYWEIGHT_SQUAT', 'Kehonpainokyykky', 'SQUAT', array['Kehonpaino']::text[], 'Seiso tukevassa asennossa. Vie lantiota alas ja taakse hallitusti. Nouse ylös pitäen polvet varpaiden suuntaisina.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-bodyweight-squat-v1","code":"BODYWEIGHT_SQUAT","version":"1.0.0","nameFi":"Kehonpainokyykky","method":"RESISTANCE","movementPatterns":["SQUAT"],"primaryMuscles":["quadriceps","gluteals"],"secondaryMuscles":["trunk"],"equipment":["Kehonpaino"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BODYWEIGHT"],"fatigue":{"systemic":2,"local":2,"neural":1,"eccentric":2,"sorenessRisk":2},"contraindicationTags":["ACUTE_KNEE_PAIN","GAIT_ALTERING_PAIN"],"prerequisiteTags":["CONTROLLED_SQUAT"],"regressionCodes":["CHAIR_SQUAT"],"progressionCodes":["GOBLET_SQUAT"],"substitutionCodes":["CHAIR_SQUAT","GOBLET_SQUAT"],"adaptationTargets":["GENERAL_STRENGTH","LOWER_BODY_STRENGTH"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001","CLAIM-ADULT-RT-ROM-001"],"instructionsFi":["Seiso tukevassa asennossa.","Vie lantiota alas ja taakse hallitusti.","Nouse ylös pitäen polvet varpaiden suuntaisina."],"status":"PUBLISHED"}'::jsonb),
  ('GOBLET_SQUAT', 'Maljakyykky', 'SQUAT', array['Käsipainot', 'Kahvakuula']::text[], 'Pidä paino vakaasti rinnan edessä. Kyykkää hallitulla ja kivuttomalla liikeradalla. Nouse ilman polvien painumista sisään.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-goblet-squat-v1","code":"GOBLET_SQUAT","version":"1.0.0","nameFi":"Maljakyykky","method":"RESISTANCE","movementPatterns":["SQUAT"],"primaryMuscles":["quadriceps","gluteals"],"secondaryMuscles":["trunk","upper back"],"equipment":["Käsipainot","Kahvakuula"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["DUMBBELL_KG_EACH","EXTERNAL_KG"],"fatigue":{"systemic":3,"local":3,"neural":2,"eccentric":2,"sorenessRisk":2},"contraindicationTags":["ACUTE_KNEE_PAIN","GAIT_ALTERING_PAIN"],"prerequisiteTags":["CONTROLLED_SQUAT"],"regressionCodes":["BODYWEIGHT_SQUAT","CHAIR_SQUAT"],"progressionCodes":["LEG_PRESS"],"substitutionCodes":["BODYWEIGHT_SQUAT","LEG_PRESS"],"adaptationTargets":["GENERAL_STRENGTH","LOWER_BODY_STRENGTH","HYPERTROPHY"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001","CLAIM-ADULT-RT-LOAD-001"],"instructionsFi":["Pidä paino vakaasti rinnan edessä.","Kyykkää hallitulla ja kivuttomalla liikeradalla.","Nouse ilman polvien painumista sisään."],"status":"PUBLISHED"}'::jsonb),
  ('LEG_PRESS', 'Jalkaprässi', 'SQUAT', array['Kuntosalilaitteet']::text[], 'Säädä istuin niin, että alaselkä pysyy tuettuna. Laske kelkka hallitusti kivuttomalle syvyydelle. Työnnä jalkapohjilla ilman polvien lukitsemista.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-leg-press-v1","code":"LEG_PRESS","version":"1.0.0","nameFi":"Jalkaprässi","method":"RESISTANCE","movementPatterns":["SQUAT"],"primaryMuscles":["quadriceps","gluteals"],"secondaryMuscles":["hamstrings"],"equipment":["Kuntosalilaitteet"],"environments":["GYM"],"unilateral":false,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"RECOMMENDED","minimumAge":18,"loadTypes":["MACHINE_KG"],"fatigue":{"systemic":3,"local":4,"neural":2,"eccentric":3,"sorenessRisk":3},"contraindicationTags":["ACUTE_KNEE_PAIN","GAIT_ALTERING_PAIN"],"prerequisiteTags":["MACHINE_SETUP"],"regressionCodes":["CHAIR_SQUAT","GOBLET_SQUAT"],"progressionCodes":[],"substitutionCodes":["GOBLET_SQUAT","CHAIR_SQUAT"],"adaptationTargets":["LOWER_BODY_STRENGTH","HYPERTROPHY","MAX_STRENGTH"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001","CLAIM-ADULT-RT-LOAD-001"],"instructionsFi":["Säädä istuin niin, että alaselkä pysyy tuettuna.","Laske kelkka hallitusti kivuttomalle syvyydelle.","Työnnä jalkapohjilla ilman polvien lukitsemista."],"status":"PUBLISHED"}'::jsonb),
  ('GLUTE_BRIDGE', 'Lantionnosto', 'HINGE', array['Kehonpaino']::text[], 'Aseta jalat tukevasti lattialle. Nosta lantio puristamalla pakaroita. Lopeta liike ennen alaselän yliojennusta.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-glute-bridge-v1","code":"GLUTE_BRIDGE","version":"1.0.0","nameFi":"Lantionnosto","method":"RESISTANCE","movementPatterns":["HINGE"],"primaryMuscles":["gluteals"],"secondaryMuscles":["hamstrings","trunk"],"equipment":["Kehonpaino"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":1,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BODYWEIGHT"],"fatigue":{"systemic":1,"local":2,"neural":1,"eccentric":1,"sorenessRisk":1},"contraindicationTags":["ACUTE_BACK_PAIN"],"prerequisiteTags":[],"regressionCodes":[],"progressionCodes":["DUMBBELL_RDL","CABLE_PULL_THROUGH"],"substitutionCodes":["DUMBBELL_RDL","CABLE_PULL_THROUGH"],"adaptationTargets":["GENERAL_STRENGTH","HIP_EXTENSION","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Aseta jalat tukevasti lattialle.","Nosta lantio puristamalla pakaroita.","Lopeta liike ennen alaselän yliojennusta."],"status":"PUBLISHED"}'::jsonb),
  ('DUMBBELL_RDL', 'Romanialainen maastaveto käsipainoilla', 'HINGE', array['Käsipainot']::text[], 'Pidä painot lähellä vartaloa. Vie lantiota taakse selän asennon säilyessä vakaana. Nouse pakaroiden ja takareisien työllä ilman nykäisyä.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-dumbbell-rdl-v1","code":"DUMBBELL_RDL","version":"1.0.0","nameFi":"Romanialainen maastaveto käsipainoilla","method":"RESISTANCE","movementPatterns":["HINGE"],"primaryMuscles":["hamstrings","gluteals"],"secondaryMuscles":["back extensors","grip"],"equipment":["Käsipainot"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":3,"minimumExperience":"BEGINNER","supervisionRequirement":"RECOMMENDED","minimumAge":18,"loadTypes":["DUMBBELL_KG_EACH"],"fatigue":{"systemic":3,"local":3,"neural":2,"eccentric":4,"sorenessRisk":3},"contraindicationTags":["ACUTE_BACK_PAIN","HAMSTRING_INJURY"],"prerequisiteTags":["CONTROLLED_HINGE"],"regressionCodes":["GLUTE_BRIDGE"],"progressionCodes":["BARBELL_RDL"],"substitutionCodes":["GLUTE_BRIDGE","BARBELL_RDL"],"adaptationTargets":["GENERAL_STRENGTH","HIP_EXTENSION","HYPERTROPHY"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001","CLAIM-ADULT-RT-LOAD-001"],"instructionsFi":["Pidä painot lähellä vartaloa.","Vie lantiota taakse selän asennon säilyessä vakaana.","Nouse pakaroiden ja takareisien työllä ilman nykäisyä."],"status":"PUBLISHED"}'::jsonb),
  ('BARBELL_RDL', 'Romanialainen maastaveto levytangolla', 'HINGE', array['Levytanko ja painot']::text[], 'Ota tasainen ote tangosta ja pidä se lähellä reisiä. Vie lantiota taakse hallitusti. Lopeta liikerata, kun selän neutraali asento ei enää säily.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-barbell-rdl-v1","code":"BARBELL_RDL","version":"1.0.0","nameFi":"Romanialainen maastaveto levytangolla","method":"RESISTANCE","movementPatterns":["HINGE"],"primaryMuscles":["hamstrings","gluteals"],"secondaryMuscles":["back extensors","grip"],"equipment":["Levytanko ja painot"],"environments":["GYM"],"unilateral":false,"technicalComplexity":4,"minimumExperience":"INTERMEDIATE","supervisionRequirement":"RECOMMENDED","minimumAge":18,"loadTypes":["EXTERNAL_KG"],"fatigue":{"systemic":4,"local":4,"neural":4,"eccentric":4,"sorenessRisk":4},"contraindicationTags":["ACUTE_BACK_PAIN","HAMSTRING_INJURY"],"prerequisiteTags":["CONTROLLED_HINGE","BARBELL_SETUP"],"regressionCodes":["DUMBBELL_RDL","GLUTE_BRIDGE"],"progressionCodes":[],"substitutionCodes":["DUMBBELL_RDL","CABLE_PULL_THROUGH"],"adaptationTargets":["MAX_STRENGTH","HIP_EXTENSION","HYPERTROPHY"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001","CLAIM-ADULT-RT-LOAD-001"],"instructionsFi":["Ota tasainen ote tangosta ja pidä se lähellä reisiä.","Vie lantiota taakse hallitusti.","Lopeta liikerata, kun selän neutraali asento ei enää säily."],"status":"PUBLISHED"}'::jsonb),
  ('CABLE_PULL_THROUGH', 'Taljaveto jalkojen välistä', 'HINGE', array['Kuntosalilaitteet']::text[], 'Asetu selkä taljaan päin ja pidä köysi jalkojen välissä. Vie lantiota taakse hallitusti. Ojenna lantio ilman alaselän yliojennusta.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-cable-pull-through-v1","code":"CABLE_PULL_THROUGH","version":"1.0.0","nameFi":"Taljaveto jalkojen välistä","method":"RESISTANCE","movementPatterns":["HINGE"],"primaryMuscles":["gluteals","hamstrings"],"secondaryMuscles":["trunk"],"equipment":["Kuntosalilaitteet"],"environments":["GYM"],"unilateral":false,"technicalComplexity":3,"minimumExperience":"BEGINNER","supervisionRequirement":"RECOMMENDED","minimumAge":18,"loadTypes":["MACHINE_KG"],"fatigue":{"systemic":2,"local":3,"neural":2,"eccentric":2,"sorenessRisk":2},"contraindicationTags":["ACUTE_BACK_PAIN"],"prerequisiteTags":["CONTROLLED_HINGE","MACHINE_SETUP"],"regressionCodes":["GLUTE_BRIDGE"],"progressionCodes":["DUMBBELL_RDL"],"substitutionCodes":["GLUTE_BRIDGE","DUMBBELL_RDL"],"adaptationTargets":["HIP_EXTENSION","HYPERTROPHY","GENERAL_STRENGTH"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Asetu selkä taljaan päin ja pidä köysi jalkojen välissä.","Vie lantiota taakse hallitusti.","Ojenna lantio ilman alaselän yliojennusta."],"status":"PUBLISHED"}'::jsonb),
  ('SUPPORTED_SPLIT_SQUAT', 'Tuettu askelkyykky paikallaan', 'SINGLE_LEG', array['Kehonpaino']::text[], 'Ota tukea vakaasta pinnasta. Laskeudu suoraan alaspäin hallitusti. Ponnista etummaisen jalan kautta takaisin ylös.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-supported-split-squat-v1","code":"SUPPORTED_SPLIT_SQUAT","version":"1.0.0","nameFi":"Tuettu askelkyykky paikallaan","method":"RESISTANCE","movementPatterns":["SINGLE_LEG","SQUAT"],"primaryMuscles":["quadriceps","gluteals"],"secondaryMuscles":["calves","trunk"],"equipment":["Kehonpaino"],"environments":["HOME","GYM"],"unilateral":true,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BODYWEIGHT"],"fatigue":{"systemic":2,"local":3,"neural":2,"eccentric":3,"sorenessRisk":3},"contraindicationTags":["ACUTE_KNEE_PAIN","BALANCE_LIMITATION","GAIT_ALTERING_PAIN"],"prerequisiteTags":["SUPPORTED_STANCE"],"regressionCodes":["CHAIR_SQUAT"],"progressionCodes":["REVERSE_LUNGE","STEP_UP"],"substitutionCodes":["STEP_UP","REVERSE_LUNGE"],"adaptationTargets":["LOWER_BODY_STRENGTH","SINGLE_LEG_CONTROL","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Ota tukea vakaasta pinnasta.","Laskeudu suoraan alaspäin hallitusti.","Ponnista etummaisen jalan kautta takaisin ylös."],"status":"PUBLISHED"}'::jsonb),
  ('REVERSE_LUNGE', 'Taakseaskelkyykky', 'SINGLE_LEG', array['Kehonpaino']::text[], 'Astu yhdellä jalalla taakse. Laskeudu hallitusti etummaisen polven seuratessa varpaiden suuntaa. Palaa alkuun etummaisen jalan voimalla.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-reverse-lunge-v1","code":"REVERSE_LUNGE","version":"1.0.0","nameFi":"Taakseaskelkyykky","method":"RESISTANCE","movementPatterns":["SINGLE_LEG","SQUAT"],"primaryMuscles":["quadriceps","gluteals"],"secondaryMuscles":["calves","trunk"],"equipment":["Kehonpaino"],"environments":["HOME","GYM"],"unilateral":true,"technicalComplexity":3,"minimumExperience":"INTERMEDIATE","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BODYWEIGHT"],"fatigue":{"systemic":3,"local":3,"neural":2,"eccentric":3,"sorenessRisk":3},"contraindicationTags":["ACUTE_KNEE_PAIN","BALANCE_LIMITATION","GAIT_ALTERING_PAIN"],"prerequisiteTags":["SINGLE_LEG_CONTROL"],"regressionCodes":["SUPPORTED_SPLIT_SQUAT"],"progressionCodes":[],"substitutionCodes":["SUPPORTED_SPLIT_SQUAT","STEP_UP"],"adaptationTargets":["LOWER_BODY_STRENGTH","SINGLE_LEG_CONTROL","HYPERTROPHY"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Astu yhdellä jalalla taakse.","Laskeudu hallitusti etummaisen polven seuratessa varpaiden suuntaa.","Palaa alkuun etummaisen jalan voimalla."],"status":"PUBLISHED"}'::jsonb),
  ('STEP_UP', 'Nousu matalalle korokkeelle', 'SINGLE_LEG', array['Kehonpaino']::text[], 'Käytä vakaata, matalaa koroketta. Nouse korokkeelle etummaisen jalan voimalla. Laskeudu hitaasti takaisin hallintaan.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-step-up-v1","code":"STEP_UP","version":"1.0.0","nameFi":"Nousu matalalle korokkeelle","method":"RESISTANCE","movementPatterns":["SINGLE_LEG"],"primaryMuscles":["quadriceps","gluteals"],"secondaryMuscles":["calves","trunk"],"equipment":["Kehonpaino"],"environments":["HOME","GYM"],"unilateral":true,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BODYWEIGHT"],"fatigue":{"systemic":2,"local":3,"neural":2,"eccentric":2,"sorenessRisk":2},"contraindicationTags":["ACUTE_KNEE_PAIN","BALANCE_LIMITATION","GAIT_ALTERING_PAIN"],"prerequisiteTags":["STABLE_STEP"],"regressionCodes":["CHAIR_SQUAT"],"progressionCodes":["REVERSE_LUNGE"],"substitutionCodes":["SUPPORTED_SPLIT_SQUAT","REVERSE_LUNGE"],"adaptationTargets":["LOWER_BODY_STRENGTH","SINGLE_LEG_CONTROL","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Käytä vakaata, matalaa koroketta.","Nouse korokkeelle etummaisen jalan voimalla.","Laskeudu hitaasti takaisin hallintaan."],"status":"PUBLISHED"}'::jsonb),
  ('ELEVATED_PUSH_UP', 'Korotettu punnerrus', 'HORIZONTAL_PUSH', array['Kehonpaino']::text[], 'Aseta kädet vakaalle korokkeelle. Pidä vartalo suorana kantapäistä päähän. Laske rintakehä hallitusti ja työnnä takaisin ilman kipua.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-elevated-push-up-v1","code":"ELEVATED_PUSH_UP","version":"1.0.0","nameFi":"Korotettu punnerrus","method":"RESISTANCE","movementPatterns":["HORIZONTAL_PUSH"],"primaryMuscles":["chest","triceps"],"secondaryMuscles":["shoulders","trunk"],"equipment":["Kehonpaino"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":1,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BODYWEIGHT"],"fatigue":{"systemic":1,"local":2,"neural":1,"eccentric":2,"sorenessRisk":2},"contraindicationTags":["ACUTE_SHOULDER_PAIN","ACUTE_WRIST_PAIN"],"prerequisiteTags":[],"regressionCodes":[],"progressionCodes":["PUSH_UP","DUMBBELL_BENCH_PRESS"],"substitutionCodes":["PUSH_UP","DUMBBELL_BENCH_PRESS"],"adaptationTargets":["UPPER_BODY_STRENGTH","HORIZONTAL_PUSH","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Aseta kädet vakaalle korokkeelle.","Pidä vartalo suorana kantapäistä päähän.","Laske rintakehä hallitusti ja työnnä takaisin ilman kipua."],"status":"PUBLISHED"}'::jsonb),
  ('PUSH_UP', 'Punnerrus', 'HORIZONTAL_PUSH', array['Kehonpaino']::text[], 'Aseta kädet hieman hartioita leveämmälle. Pidä vartalo yhtenäisenä. Laske hallitusti ja työnnä ylös ilman hartioiden kohoamista.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-push-up-v1","code":"PUSH_UP","version":"1.0.0","nameFi":"Punnerrus","method":"RESISTANCE","movementPatterns":["HORIZONTAL_PUSH"],"primaryMuscles":["chest","triceps"],"secondaryMuscles":["shoulders","trunk"],"equipment":["Kehonpaino"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":3,"minimumExperience":"INTERMEDIATE","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BODYWEIGHT"],"fatigue":{"systemic":2,"local":3,"neural":2,"eccentric":3,"sorenessRisk":2},"contraindicationTags":["ACUTE_SHOULDER_PAIN","ACUTE_WRIST_PAIN"],"prerequisiteTags":["PLANK_CONTROL"],"regressionCodes":["ELEVATED_PUSH_UP"],"progressionCodes":["DUMBBELL_BENCH_PRESS"],"substitutionCodes":["ELEVATED_PUSH_UP","DUMBBELL_BENCH_PRESS"],"adaptationTargets":["UPPER_BODY_STRENGTH","HORIZONTAL_PUSH","HYPERTROPHY"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Aseta kädet hieman hartioita leveämmälle.","Pidä vartalo yhtenäisenä.","Laske hallitusti ja työnnä ylös ilman hartioiden kohoamista."],"status":"PUBLISHED"}'::jsonb),
  ('DUMBBELL_BENCH_PRESS', 'Käsipainopenkkipunnerrus', 'HORIZONTAL_PUSH', array['Käsipainot']::text[], 'Aseta jalat tukevasti ja lapaluut penkkiä vasten. Laske painot hallitusti kyynärpäät hieman vartalon alapuolella. Työnnä painot ylös ilman olkapääkivun provosointia.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-dumbbell-bench-press-v1","code":"DUMBBELL_BENCH_PRESS","version":"1.0.0","nameFi":"Käsipainopenkkipunnerrus","method":"RESISTANCE","movementPatterns":["HORIZONTAL_PUSH"],"primaryMuscles":["chest","triceps"],"secondaryMuscles":["shoulders"],"equipment":["Käsipainot"],"environments":["GYM","HOME"],"unilateral":false,"technicalComplexity":3,"minimumExperience":"BEGINNER","supervisionRequirement":"RECOMMENDED","minimumAge":18,"loadTypes":["DUMBBELL_KG_EACH"],"fatigue":{"systemic":2,"local":4,"neural":2,"eccentric":3,"sorenessRisk":3},"contraindicationTags":["ACUTE_SHOULDER_PAIN"],"prerequisiteTags":["SAFE_DUMBBELL_SETUP"],"regressionCodes":["ELEVATED_PUSH_UP"],"progressionCodes":[],"substitutionCodes":["ELEVATED_PUSH_UP","PUSH_UP"],"adaptationTargets":["UPPER_BODY_STRENGTH","HORIZONTAL_PUSH","HYPERTROPHY","MAX_STRENGTH"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001","CLAIM-ADULT-RT-LOAD-001"],"instructionsFi":["Aseta jalat tukevasti ja lapaluut penkkiä vasten.","Laske painot hallitusti kyynärpäät hieman vartalon alapuolella.","Työnnä painot ylös ilman olkapääkivun provosointia."],"status":"PUBLISHED"}'::jsonb),
  ('DUMBBELL_OVERHEAD_PRESS', 'Käsipainopystypunnerrus', 'VERTICAL_PUSH', array['Käsipainot']::text[], 'Pidä vartalo vakaana ja kylkiluut hallinnassa. Työnnä painot ylös kivuttomalla liikeradalla. Laske painot rauhallisesti takaisin.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-dumbbell-overhead-press-v1","code":"DUMBBELL_OVERHEAD_PRESS","version":"1.0.0","nameFi":"Käsipainopystypunnerrus","method":"RESISTANCE","movementPatterns":["VERTICAL_PUSH"],"primaryMuscles":["shoulders","triceps"],"secondaryMuscles":["trunk"],"equipment":["Käsipainot"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":3,"minimumExperience":"INTERMEDIATE","supervisionRequirement":"RECOMMENDED","minimumAge":18,"loadTypes":["DUMBBELL_KG_EACH"],"fatigue":{"systemic":2,"local":3,"neural":3,"eccentric":2,"sorenessRisk":2},"contraindicationTags":["ACUTE_SHOULDER_PAIN","OVERHEAD_RESTRICTION"],"prerequisiteTags":["PAIN_FREE_OVERHEAD_RANGE"],"regressionCodes":["ELEVATED_PUSH_UP"],"progressionCodes":["MACHINE_SHOULDER_PRESS"],"substitutionCodes":["MACHINE_SHOULDER_PRESS","ELEVATED_PUSH_UP"],"adaptationTargets":["UPPER_BODY_STRENGTH","VERTICAL_PUSH","HYPERTROPHY"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Pidä vartalo vakaana ja kylkiluut hallinnassa.","Työnnä painot ylös kivuttomalla liikeradalla.","Laske painot rauhallisesti takaisin."],"status":"PUBLISHED"}'::jsonb),
  ('MACHINE_SHOULDER_PRESS', 'Pystypunnerrus laitteessa', 'VERTICAL_PUSH', array['Kuntosalilaitteet']::text[], 'Säädä istuin niin, että kahvat alkavat hartioiden tasolta. Pidä selkä tuettuna. Työnnä ja palauta kuorma hallitusti kivuttomalla liikeradalla.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-machine-shoulder-press-v1","code":"MACHINE_SHOULDER_PRESS","version":"1.0.0","nameFi":"Pystypunnerrus laitteessa","method":"RESISTANCE","movementPatterns":["VERTICAL_PUSH"],"primaryMuscles":["shoulders","triceps"],"secondaryMuscles":["upper chest"],"equipment":["Kuntosalilaitteet"],"environments":["GYM"],"unilateral":false,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"RECOMMENDED","minimumAge":18,"loadTypes":["MACHINE_KG"],"fatigue":{"systemic":2,"local":3,"neural":2,"eccentric":2,"sorenessRisk":2},"contraindicationTags":["ACUTE_SHOULDER_PAIN","OVERHEAD_RESTRICTION"],"prerequisiteTags":["MACHINE_SETUP","PAIN_FREE_OVERHEAD_RANGE"],"regressionCodes":["ELEVATED_PUSH_UP"],"progressionCodes":["DUMBBELL_OVERHEAD_PRESS"],"substitutionCodes":["DUMBBELL_OVERHEAD_PRESS","ELEVATED_PUSH_UP"],"adaptationTargets":["UPPER_BODY_STRENGTH","VERTICAL_PUSH","HYPERTROPHY"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Säädä istuin niin, että kahvat alkavat hartioiden tasolta.","Pidä selkä tuettuna.","Työnnä ja palauta kuorma hallitusti kivuttomalla liikeradalla."],"status":"PUBLISHED"}'::jsonb),
  ('ONE_ARM_ROW', 'Yhden käden soutu', 'HORIZONTAL_PULL', array['Käsipainot', 'Kahvakuula']::text[], 'Tue vapaa käsi vakaasti. Vedä kyynärpää kohti kylkeä ilman vartalon kiertoa. Palauta paino hallitusti hartiaa nykäisemättä.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-one-arm-row-v1","code":"ONE_ARM_ROW","version":"1.0.0","nameFi":"Yhden käden soutu","method":"RESISTANCE","movementPatterns":["HORIZONTAL_PULL"],"primaryMuscles":["latissimus","upper back"],"secondaryMuscles":["biceps","trunk"],"equipment":["Käsipainot","Kahvakuula"],"environments":["HOME","GYM"],"unilateral":true,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["DUMBBELL_KG_EACH","EXTERNAL_KG"],"fatigue":{"systemic":2,"local":3,"neural":2,"eccentric":2,"sorenessRisk":2},"contraindicationTags":["ACUTE_SHOULDER_PAIN","ACUTE_BACK_PAIN"],"prerequisiteTags":["SUPPORTED_HINGE"],"regressionCodes":["BAND_ROW"],"progressionCodes":["SEATED_CABLE_ROW"],"substitutionCodes":["SEATED_CABLE_ROW","BAND_ROW"],"adaptationTargets":["UPPER_BODY_STRENGTH","HORIZONTAL_PULL","HYPERTROPHY"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Tue vapaa käsi vakaasti.","Vedä kyynärpää kohti kylkeä ilman vartalon kiertoa.","Palauta paino hallitusti hartiaa nykäisemättä."],"status":"PUBLISHED"}'::jsonb),
  ('SEATED_CABLE_ROW', 'Istumasoutu taljassa', 'HORIZONTAL_PULL', array['Kuntosalilaitteet']::text[], 'Istu ryhdikkäästi ja pidä jalkaterät tuettuina. Vedä kahva kohti vartaloa ilman taakse keinumista. Palauta kuorma hallitusti.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-seated-cable-row-v1","code":"SEATED_CABLE_ROW","version":"1.0.0","nameFi":"Istumasoutu taljassa","method":"RESISTANCE","movementPatterns":["HORIZONTAL_PULL"],"primaryMuscles":["upper back","latissimus"],"secondaryMuscles":["biceps"],"equipment":["Kuntosalilaitteet"],"environments":["GYM"],"unilateral":false,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"RECOMMENDED","minimumAge":18,"loadTypes":["MACHINE_KG"],"fatigue":{"systemic":2,"local":3,"neural":2,"eccentric":2,"sorenessRisk":2},"contraindicationTags":["ACUTE_SHOULDER_PAIN"],"prerequisiteTags":["MACHINE_SETUP"],"regressionCodes":["BAND_ROW"],"progressionCodes":["ONE_ARM_ROW"],"substitutionCodes":["ONE_ARM_ROW","BAND_ROW"],"adaptationTargets":["UPPER_BODY_STRENGTH","HORIZONTAL_PULL","HYPERTROPHY"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Istu ryhdikkäästi ja pidä jalkaterät tuettuina.","Vedä kahva kohti vartaloa ilman taakse keinumista.","Palauta kuorma hallitusti."],"status":"PUBLISHED"}'::jsonb),
  ('BAND_ROW', 'Soutu vastuskuminauhalla', 'HORIZONTAL_PULL', array['Vastuskuminauhat']::text[], 'Kiinnitä nauha ehjään ja vakaaseen pisteeseen. Vedä kyynärpäät kohti kylkiä. Palauta kädet hallitusti ja pidä hartiat rentoina.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-band-row-v1","code":"BAND_ROW","version":"1.0.0","nameFi":"Soutu vastuskuminauhalla","method":"RESISTANCE","movementPatterns":["HORIZONTAL_PULL"],"primaryMuscles":["upper back","latissimus"],"secondaryMuscles":["biceps"],"equipment":["Vastuskuminauhat"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":1,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BAND"],"fatigue":{"systemic":1,"local":2,"neural":1,"eccentric":1,"sorenessRisk":1},"contraindicationTags":["ACUTE_SHOULDER_PAIN"],"prerequisiteTags":["SAFE_BAND_ANCHOR"],"regressionCodes":[],"progressionCodes":["ONE_ARM_ROW","SEATED_CABLE_ROW"],"substitutionCodes":["ONE_ARM_ROW","SEATED_CABLE_ROW"],"adaptationTargets":["UPPER_BODY_STRENGTH","HORIZONTAL_PULL","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Kiinnitä nauha ehjään ja vakaaseen pisteeseen.","Vedä kyynärpäät kohti kylkiä.","Palauta kädet hallitusti ja pidä hartiat rentoina."],"status":"PUBLISHED"}'::jsonb),
  ('LAT_PULLDOWN', 'Ylätalja', 'VERTICAL_PULL', array['Kuntosalilaitteet']::text[], 'Säädä reisituki ja ota tasainen ote. Vedä tanko rintakehän yläosaa kohti ilman taakse nojaamista. Palauta kädet hallitusti ylös.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-lat-pulldown-v1","code":"LAT_PULLDOWN","version":"1.0.0","nameFi":"Ylätalja","method":"RESISTANCE","movementPatterns":["VERTICAL_PULL"],"primaryMuscles":["latissimus","upper back"],"secondaryMuscles":["biceps"],"equipment":["Kuntosalilaitteet"],"environments":["GYM"],"unilateral":false,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"RECOMMENDED","minimumAge":18,"loadTypes":["MACHINE_KG"],"fatigue":{"systemic":2,"local":3,"neural":2,"eccentric":2,"sorenessRisk":2},"contraindicationTags":["ACUTE_SHOULDER_PAIN","OVERHEAD_RESTRICTION"],"prerequisiteTags":["MACHINE_SETUP","PAIN_FREE_OVERHEAD_RANGE"],"regressionCodes":["BAND_VERTICAL_PULL"],"progressionCodes":["ASSISTED_PULL_UP"],"substitutionCodes":["ASSISTED_PULL_UP","BAND_VERTICAL_PULL"],"adaptationTargets":["UPPER_BODY_STRENGTH","VERTICAL_PULL","HYPERTROPHY"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Säädä reisituki ja ota tasainen ote.","Vedä tanko rintakehän yläosaa kohti ilman taakse nojaamista.","Palauta kädet hallitusti ylös."],"status":"PUBLISHED"}'::jsonb),
  ('ASSISTED_PULL_UP', 'Avustettu leuanveto laitteessa', 'VERTICAL_PULL', array['Kuntosalilaitteet']::text[], 'Säädä avustus niin, että toistot pysyvät hallittuina. Vedä rintakehää kohti kahvoja hartioita kohauttamatta. Laskeudu rauhallisesti täyteen hallittuun asentoon.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-assisted-pull-up-v1","code":"ASSISTED_PULL_UP","version":"1.0.0","nameFi":"Avustettu leuanveto laitteessa","method":"RESISTANCE","movementPatterns":["VERTICAL_PULL"],"primaryMuscles":["latissimus","upper back"],"secondaryMuscles":["biceps","grip"],"equipment":["Kuntosalilaitteet"],"environments":["GYM"],"unilateral":false,"technicalComplexity":3,"minimumExperience":"INTERMEDIATE","supervisionRequirement":"RECOMMENDED","minimumAge":18,"loadTypes":["MACHINE_KG"],"fatigue":{"systemic":3,"local":4,"neural":3,"eccentric":3,"sorenessRisk":3},"contraindicationTags":["ACUTE_SHOULDER_PAIN","OVERHEAD_RESTRICTION"],"prerequisiteTags":["PAIN_FREE_OVERHEAD_RANGE","MACHINE_SETUP"],"regressionCodes":["LAT_PULLDOWN","BAND_VERTICAL_PULL"],"progressionCodes":[],"substitutionCodes":["LAT_PULLDOWN","BAND_VERTICAL_PULL"],"adaptationTargets":["UPPER_BODY_STRENGTH","VERTICAL_PULL","MAX_STRENGTH"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001","CLAIM-ADULT-RT-LOAD-001"],"instructionsFi":["Säädä avustus niin, että toistot pysyvät hallittuina.","Vedä rintakehää kohti kahvoja hartioita kohauttamatta.","Laskeudu rauhallisesti täyteen hallittuun asentoon."],"status":"PUBLISHED"}'::jsonb),
  ('BAND_VERTICAL_PULL', 'Pystysuuntainen veto vastuskuminauhalla', 'VERTICAL_PULL', array['Vastuskuminauhat']::text[], 'Kiinnitä nauha varmasti pään yläpuolelle. Vedä kyynärpäät kohti kylkiä kivuttomalla liikeradalla. Palauta nauha hitaasti hallintaan.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-band-vertical-pull-v1","code":"BAND_VERTICAL_PULL","version":"1.0.0","nameFi":"Pystysuuntainen veto vastuskuminauhalla","method":"RESISTANCE","movementPatterns":["VERTICAL_PULL"],"primaryMuscles":["latissimus","upper back"],"secondaryMuscles":["biceps"],"equipment":["Vastuskuminauhat"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BAND"],"fatigue":{"systemic":1,"local":2,"neural":1,"eccentric":1,"sorenessRisk":1},"contraindicationTags":["ACUTE_SHOULDER_PAIN","OVERHEAD_RESTRICTION"],"prerequisiteTags":["SAFE_BAND_ANCHOR","PAIN_FREE_OVERHEAD_RANGE"],"regressionCodes":["BAND_ROW"],"progressionCodes":["LAT_PULLDOWN"],"substitutionCodes":["LAT_PULLDOWN","BAND_ROW"],"adaptationTargets":["UPPER_BODY_STRENGTH","VERTICAL_PULL","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Kiinnitä nauha varmasti pään yläpuolelle.","Vedä kyynärpäät kohti kylkiä kivuttomalla liikeradalla.","Palauta nauha hitaasti hallintaan."],"status":"PUBLISHED"}'::jsonb),
  ('STANDING_CALF_RAISE', 'Seisten pohjenousu', 'CALF_RAISE', array['Kehonpaino']::text[], 'Ota kevyt tuki tarvittaessa. Nouse päkiöille hallitusti. Laske kantapäät rauhallisesti ilman pomppua.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-standing-calf-raise-v1","code":"STANDING_CALF_RAISE","version":"1.0.0","nameFi":"Seisten pohjenousu","method":"RESISTANCE","movementPatterns":["CALF_RAISE"],"primaryMuscles":["calves"],"secondaryMuscles":["foot stabilizers"],"equipment":["Kehonpaino"],"environments":["HOME","GYM"],"unilateral":false,"technicalComplexity":1,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BODYWEIGHT"],"fatigue":{"systemic":1,"local":3,"neural":1,"eccentric":2,"sorenessRisk":2},"contraindicationTags":["ACHILLES_PAIN","CALF_INJURY","GAIT_ALTERING_PAIN"],"prerequisiteTags":["SUPPORTED_STANCE"],"regressionCodes":[],"progressionCodes":[],"substitutionCodes":["CHAIR_SQUAT","STEP_UP"],"adaptationTargets":["CALF_STRENGTH","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Ota kevyt tuki tarvittaessa.","Nouse päkiöille hallitusti.","Laske kantapäät rauhallisesti ilman pomppua."],"status":"PUBLISHED"}'::jsonb),
  ('DEAD_BUG', 'Dead bug', 'ANTI_EXTENSION', array['Kehonpaino']::text[], 'Asetu selinmakuulle ja hengitä rauhallisesti. Ojenna vastakkainen käsi ja jalka ilman selän asennon muuttumista. Palaa alkuun hallitusti.', 'adult-resistance-v1.0.0', '1.0.0', '{"id":"exercise-dead-bug-v1","code":"DEAD_BUG","version":"1.0.0","nameFi":"Dead bug","method":"RESISTANCE","movementPatterns":["ANTI_EXTENSION"],"primaryMuscles":["trunk"],"secondaryMuscles":["hip flexors"],"equipment":["Kehonpaino"],"environments":["HOME","GYM"],"unilateral":true,"technicalComplexity":2,"minimumExperience":"BEGINNER","supervisionRequirement":"NONE","minimumAge":18,"loadTypes":["BODYWEIGHT"],"fatigue":{"systemic":1,"local":2,"neural":1,"eccentric":1,"sorenessRisk":1},"contraindicationTags":["ACUTE_BACK_PAIN"],"prerequisiteTags":[],"regressionCodes":[],"progressionCodes":["FRONT_PLANK"],"substitutionCodes":["BIRD_DOG","FRONT_PLANK"],"adaptationTargets":["TRUNK_CONTROL","FUNCTION"],"sportTags":[],"positionTags":[],"evidenceClaimIds":["CLAIM-ADULT-RT-BASE-001"],"instructionsFi":["Asetu selinmakuulle ja hengitä rauhallisesti.","Ojenna vastakkainen käsi ja jalka ilman selän asennon muuttumista.","Palaa alkuun hallitusti."],"status":"PUBLISHED"}'::jsonb),
