values ('adult-resistance-v1.0.0', '1.0.0', 'INTERNAL_BETA', '5e4e72efd00a8503bf2faf85cef9d93ae8906ab95d4f475a7365111764fd1c8a', '2026-08-25T12:00:00.000Z', true)
on conflict (release_id) do nothing;

do $verify_release$
begin
  if not exists (
    select 1 from public.training_content_releases
    where release_id = 'adult-resistance-v1.0.0'
      and content_digest = '5e4e72efd00a8503bf2faf85cef9d93ae8906ab95d4f475a7365111764fd1c8a'
      and semantic_version = '1.0.0'
  ) then
    raise exception 'training content release identity does not match immutable digest';
  end if;
end;
$verify_release$;

on conflict (content_release_id, exercise_code, definition_version) do nothing;

on conflict (code) do update set
